import { configureStore, createSlice, PayloadAction } from '@reduxjs/toolkit';

// Define the state shape
interface CounterState {
  value: number;
  status: 'idle' | 'loading';
}

const initialState: CounterState = {
  value: 0,
  status: 'idle',
};

// Create a slice: reducers + actions generated automatically
const counterSlice = createSlice({
  name: 'counter',
  initialState,
  reducers: {
    increment: (state) => {
      // Immer allows "mutating" syntax that produces immutable updates
      state.value += 1;
    },
    decrement: (state) => {
      state.value -= 1;
    },
    incrementByAmount: (state, action: PayloadAction<number>) => {
      state.value += action.payload;
    },
    setStatus: (state, action: PayloadAction<'idle' | 'loading'>) => {
      state.status = action.payload;
    },
  },
});

// Auto-generated action creators
export const { increment, decrement, incrementByAmount, setStatus } = counterSlice.actions;

// Create the store
export const store = configureStore({
  reducer: {
    counter: counterSlice.reducer,
  },
});

// TypeScript types for the store
export type RootState = ReturnType<typeof store.getState>;
export type AppDispatch = typeof store.dispatch;

