    queryKey: ['todos'],
    queryFn: async () => {
      const response = await fetch('/api/todos');
      if (!response.ok) throw new Error('Failed to fetch todos');
      return response.json();
    },
    staleTime: 1000 * 30, // 30 seconds
  });

  if (isLoading) return <div>Loading todos...</div>;
